(()=>{"use strict";const reduce=matchMedia("(prefers-reduced-motion: reduce)").matches;const start=()=>{if(reduce||!window.gsap)return;const hero=document.querySelector(".hero");const heroItems=hero?hero.querySelectorAll(".tag,.eyebrow,h1,p,.artnote"):[];if(heroItems.length){gsap.fromTo(heroItems,{autoAlpha:0,y:18},{autoAlpha:1,y:0,duration:.72,stagger:.11,ease:"power2.out",clearProps:"transform,opacity,visibility"});}const sections=[...document.querySelectorAll("main > section")];if(!sections.length)return;sections.forEach(section=>{gsap.set(section,{autoAlpha:0,y:22});});const reveal=section=>gsap.to(section,{autoAlpha:1,y:0,duration:.62,ease:"power2.out",overwrite:true,clearProps:"transform,opacity,visibility"});if(!("IntersectionObserver" in window)){sections.forEach(reveal);return;}const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){reveal(entry.target);observer.unobserve(entry.target);}}),{threshold:.12,rootMargin:"0px 0px -7%"});sections.forEach(section=>observer.observe(section));const call=document.querySelector(".callout,.call");if(call)gsap.to(call,{boxShadow:"0 15px 35px rgba(179,60,47,.16)",duration:1.4,delay:.8,yoyo:true,repeat:1,ease:"sine.inOut"});};if(window.gsap){start();return;}const tag=document.createElement("script");tag.src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/gsap.min.js";tag.integrity="sha512-f6bQMg6nk8GA0X5c6L0SIYJDzH6qYQADbyZ/yvdCJn6VH4jtAFV6STpWcy+i2FphKnhFzwR5p7tQokpWk3FIQ==";tag.crossOrigin="anonymous";tag.onload=start;tag.onerror=()=>{};document.head.appendChild(tag);})();
